insert into public.standards (code,kind,title,en,owner,support,version,status,scope,summary,file,link,tokens,clauses,sort) values ($s$AAHC-FM-STD-DIGITAL-SIGNAGE-001$s$,$s$internal$s$,$s$معيار الشاشات الرقمية والتلفزيونات$s$,$s$Digital Signage & TV Installation Standard$s$,$s$FAC$s$,array[$s$IT$s$,$s$PRJ$s$]::text[],$s$Rev 0$s$,$s$draft$s$,$s$اختيار الشاشات وتركيبها وتشغيلها وإدارة محتواها في كل منشآت التجمع: المستشفيات والمراكز والمباني الإدارية والمناطق العامة والانتظار والاستقبال ومحطات التمريض والمكاتب وغرف الاجتماعات.$s$,$s$شاشات تجارية للتشغيل المتواصل (Samsung QMC القياسي، QHC للإضاءة العالية، QBC للمناطق الإدارية غير الحرجة) بدقة 4K، ولا تلفزيون منزلي في المناطق العامة؛ مقبسان ونقطة شبكة خلف كل شاشة وكابلات مخفية؛ وربط شاشات المناطق العامة بمنصة Navori؛ ومقاسات وارتفاعات محددة لكل موقع.$s$,$s$assets/standards/AAHC-FM-STD-DIGITAL-SIGNAGE-001.pdf$s$,'',array[$s$AAHC-FM-STD-DIGITAL-SIGNAGE-001$s$,$s$Navori$s$,$s$Samsung QMC$s$,$s$QMC$s$]::text[],$s$["الغرض: نهج موحد لاختيار الشاشات وتركيبها وتشغيلها وإدارتها في كل منشآت التجمع.", "المتطلبات العامة: شاشات احترافية تجارية للتشغيل المتواصل، وSamsung QMC أو ما يعادلها المعتمد هي الأساس؛ لا يُركَّب تلفزيون منزلي في المناطق العامة أو الحرجة؛ دقة 4K UHD كحد أدنى؛ حوامل تجارية معتمدة.", "الأنواع المعتمدة: QMC للتطبيقات الصحية القياسية، QHC للمناطق عالية الإضاءة، QBC للمناطق الإدارية غير الحرجة.", "الكهرباء: مقبسان كحد أدنى خلف كل شاشة (للشاشة وللمشغّل)، مخفيان خلفها، ويُفضَّل ربط أحدهما بالطوارئ/UPS.", "الشبكة: نقطة RJ45 سلكية لكل شاشة؛ والاتصال اللاسلكي بموافقة تقنية المعلومات فقط.", "الكابلات: كل الكابلات مخفية خلف الشاشة أو في مجارٍ معتمدة؛ لا أسلاك متدلية ولا تمديدات مؤقتة.", "ارتفاع منتصف الشاشة عن الأرضية المنتهية: الانتظار الصغيرة 1.5–1.7 م، الكبيرة 1.5–1.8 م، الاستقبال 1.5–1.7 م، محطات التمريض 1.6–1.8 م، المكاتب 1.4–1.6 م، المكاتب التنفيذية 1.3–1.5 م، الاجتماعات 1.2–1.4 م، الردهات الرئيسية 1.7–2.0 م.", "المقاسات: الانتظار الصغيرة 43–55، القياسية 55–65، الكبيرة 65، الردهات 65–75، القاعات الكبيرة 75 فأكثر، التمريض والاستقبال 43–55، المكاتب 55، التنفيذية والاجتماعات 55–65 بوصة.", "إدارة المحتوى: كل شاشات المناطق العامة مربوطة بمنصة Navori (مشغّل مدمج أو خارجي): التوعية الصحية، الدور، أوقات الانتظار، الإرشاد، التنبيهات الطارئة. ويُوصى بربط المكاتب والاجتماعات أيضاً.", "الحوكمة: كل تركيب جديد يلتزم بالمعيار، وأي خروج عنه بموافقة موثقة؛ وتنسّق المرافق وتقنية المعلومات والاتصال المؤسسي والمشاريع."]$s$::jsonb,0) on conflict (code) do nothing;
insert into public.standards (code,kind,title,en,owner,support,version,status,scope,summary,file,link,tokens,clauses,sort) values ($s$AHC-PRJ-HO$s$,$s$internal$s$,$s$اشتراطات تسليم المشروع$s$,$s$Project Handover Requirements$s$,$s$PRJ$s$,array[$s$FAC$s$,$s$MNT$s$]::text[],'',$s$active$s$,$s$ما يلتزم المقاول بتسليمه في كل مشروع: المخططات كما نُفِّذ، الضمانات والشهادات، الترميز والتوسيم، التشغيل والصيانة والتدريب، فترة الضمان والاستلام النهائي.$s$,$s$26 اشتراطاً (HO-01..HO-26) تُرفق بجداول الكميات ويُولَّد منها بند «الإغلاق والضمان» في المشروع.$s$,'',$s$#/handover$s$,array[$s$HO-$s$]::text[],$s$[]$s$::jsonb,10) on conflict (code) do nothing;
insert into public.standards (code,kind,title,en,owner,support,version,status,scope,summary,file,link,tokens,clauses,sort) values ($s$AHC-PRJ-SPEC$s$,$s$internal$s$,$s$دليل المواصفات المعتمدة للتشطيبات والتجهيزات$s$,$s$Approved Specifications Guide$s$,$s$PRJ$s$,'{}'::text[],'',$s$active$s$,$s$الشائع في السوق مقابل المعتمد لدى التجمع لكل بند محدد العلامة في جداول الكميات، وسبب الاعتماد وما يُقدَّم قبل التوريد.$s$,$s$يصدر من جدول كميات أي مشروع باسمه بالعربية والإنجليزية، وبطاقاته تُدار من الإدارة ← دليل المواصفات.$s$,'',$s$#guide$s$,'{}'::text[],$s$[]$s$::jsonb,20) on conflict (code) do nothing;
insert into public.standards (code,kind,title,en,owner,support,version,status,scope,summary,file,link,tokens,clauses,sort) values ($s$AHC-DSG$s$,$s$internal$s$,$s$دليل معايير التصميم للمنشآت الصحية$s$,$s$Healthcare Facility Design Standards Guide$s$,$s$PRJ$s$,array[$s$FAC$s$,$s$IT$s$,$s$BME$s$]::text[],'',$s$active$s$,$s$مبادئ التصميم ومساره، الفراغات النموذجية، الهوية والإرشاد، الخامات، ترميز الغرف، الأنظمة، التصميم للصيانة، الوصول الشامل، ومخرجات التصميم وقائمة مراجعته.$s$,$s$يُرفق مع كل تكليف تصميم أو تأهيل، ولا يُعتمد تصميم للطرح قبل اجتياز قائمة مراجعته (R-44).$s$,'',$s$#/manuals/g/design$s$,'{}'::text[],$s$[]$s$::jsonb,30) on conflict (code) do nothing;
insert into public.standards (code,kind,title,en,owner,support,version,status,scope,summary,file,link,tokens,clauses,sort) values ($s$AHC-CTR$s$,$s$internal$s$,$s$دليل المقاول للعمل داخل المنشآت المشغّلة$s$,$s$Contractor Guide for Work in Operating Facilities$s$,$s$PRJ$s$,array[$s$SAF$s$,$s$FAC$s$]::text[],'',$s$active$s$,$s$قبل المباشرة، الدخول والحركة، تصاريح العمل، مكافحة العدوى أثناء الأعمال، السلامة، الإيقافات، المخلفات، الجودة والاعتمادات، الحوادث، الاستلام، المخالفات، وإقرار المقاول.$s$,$s$جزء من العقد (R-43)، ويُوقّع المقاول إقراره قبل المباشرة.$s$,'',$s$#/manuals/g/contractor$s$,'{}'::text[],$s$[]$s$::jsonb,40) on conflict (code) do nothing;
insert into public.standards (code,kind,title,en,owner,support,version,status,scope,summary,file,link,tokens,clauses,sort) values ($s$AHC-CODE$s$,$s$internal$s$,$s$نظام ترميز الغرف والأصول$s$,$s$Room and Asset Coding System$s$,$s$FAC$s$,array[$s$PRJ$s$,$s$MNT$s$,$s$BME$s$]::text[],'',$s$active$s$,$s$رمز ثابت لكل فراغ (القسم/المنطقة – الطابق – رقم الغرفة) يُكتب على المخططات ولوحة الغرفة ويُسجَّل في المنصة، وترميز الأصول بلوحات QR وفق موقعها في Planon.$s$,$s$كل بلاغ على رقم غرفة أو أصل (R-16)، ويطبّقه المقاول عند التسليم (HO-16، HO-17).$s$,'',$s$#/manuals/g/design$s$,array[$s$ترقيم الغرف$s$,$s$ترميز الأصول$s$,$s$Planon$s$]::text[],$s$["مثال الرمز: ER-GF-001 (القسم – الطابق – الغرفة).", "لا يتغير الرمز بتغيير الاستخدام إلا بإجراء إدارة التغيير (G-12).", "الأصول بلوحات دائمة تحمل رمز QR: رمز الموقع في Planon / المبنى / الدور / الغرفة / نوع الأصل / الرقم التسلسلي."]$s$::jsonb,50) on conflict (code) do nothing;
